settings.migrate:
(values, { scope, from }) => {
  if (from === "1.0.0") {
    if (scope === "global" && typeof values.useModelIds === "boolean") {
      return { labelMode: values.useModelIds ? "id" : "name" };
    }
    if (scope === "workspace" && typeof values.includeDisabled === "boolean") {
      return { showDisabled: values.includeDisabled };
    }
  }
  return values;
}

settingsPages.program:
{
  view({ settings }) {
    const { values, revision } = settings.global;
    return {
      schema: 1,
      title: "目录显示设置",
      blocks: [
        {
          type: "form",
          id: "display",
          presentation: "inline",
          revision,
          fields: [
            {
              type: "select",
              name: "labelMode",
              label: "概览中显示",
              help: "此设置对所有工作区生效。",
              value: values.labelMode,
              required: true,
              options: [
                { value: "name", label: "模型名称" },
                { value: "id", label: "模型 ID" },
              ],
            },
          ],
          submit: { action: "save", label: "保存设置" },
        },
      ],
    };
  },
}

{
  view({ settings, models }) {
    const { showDisabled } = settings.workspace.values;
    const label = showDisabled ? "隐藏停用模型" : "显示停用模型";
    return {
      schema: 1,
      title: "示例模型概览",
      primary: {
        action: "toggle-disabled",
        label,
        confirm: {
          title: label,
          summary: "更改当前工作区的模型列表显示方式。",
        },
      },
      blocks: [
        {
          type: "list",
          empty: "当前没有符合显示条件的模型。",
          rows: models
            .filter((model) => showDisabled || model.enabled)
            .map((model) => ({
              id: model.id,
              title:
                settings.global.values.labelMode === "id"
                  ? model.id
                  : model.label,
              status: model.enabled ? "已启用" : "已停用",
            })),
        },
      ],
    };
  },
  action(id, payload, { settings }) {
    if (id !== "toggle-disabled") throw Error("未知操作");
    const showDisabled = !settings.workspace.values.showDisabled;
    return {
      settings: { workspace: { showDisabled } },
      notice: showDisabled
        ? "当前工作区已显示停用模型"
        : "当前工作区已隐藏停用模型",
    };
  },
}

{
  // Hooks may be async. `host` holds the functions this package declared:
  // a view can read, an action can also write.
  async view(input, host) {
    const { keys } = await host.data.list("notes/");
    const rows = [];
    for (const key of keys) {
      const note = await host.data.get(key);
      rows.push({
        id: key,
        title: note.text,
        status: note.savedAt,
        actions: [
          {
            action: "remove-note",
            label: "删除",
            payload: { key },
            confirm: { title: "删除备注", summary: note.text },
          },
        ],
      });
    }
    return {
      schema: 1,
      title: "工作区备注",
      blocks: [
        {
          type: "form",
          id: "add",
          presentation: "inline",
          fields: [
            { name: "text", label: "备注", type: "text", required: true },
          ],
          submit: { action: "add-note", label: "保存备注" },
        },
        { type: "list", empty: "当前工作区还没有备注。", rows },
      ],
    };
  },
  async action(id, payload, input, host) {
    if (id === "add-note") {
      const text = String(payload.text || "").trim();
      if (!text) throw Error("备注不能为空");
      const { keys } = await host.data.list("notes/");
      const next =
        keys.reduce((max, key) => Math.max(max, Number(key.slice(6))), 0) + 1;
      await host.data.put("notes/" + String(next).padStart(6, "0"), {
        text: text.slice(0, 200),
        savedAt: payload.savedAt || "",
      });
      return { notice: "备注已保存" };
    }
    if (id === "remove-note") {
      await host.data.delete(String(payload.key));
      return { notice: "备注已删除" };
    }
    throw Error("未知操作");
  },
}
